from pathlib import Path
from PIL import Image, ImageDraw, ImageFont
import json,os
root=Path(__file__).resolve().parents[1]
folder=root/os.environ.get('MAP_REVIEW_DIR','evidence/map-visual-v12/before')
data=json.loads((folder/'capture.json').read_text(encoding='utf8'))
review_path=folder.parent/'reviews.json'
reviews=json.loads(review_path.read_text(encoding='utf8')) if review_path.exists() else {}
font=ImageFont.truetype('C:/Windows/Fonts/msyh.ttc',18);small=ImageFont.truetype('C:/Windows/Fonts/msyh.ttc',14)
(folder/'sheets').mkdir(exist_ok=True)
for m in data['maps']:
 m['review']=reviews.get(str(m['stage']),m['review'])
 if os.environ.get('SKIP_SHEETS')=='1':continue
 if os.environ.get('SKIP_SHEETS')=='1':continue
 for kind in ['route','states']:
  frames=[f for f in m['frames'] if f['id'].startswith('route-')== (kind=='route')]
  sheet=Image.new('RGB',(1168,64+350*((len(frames)+1)//2)),'#101922');draw=ImageDraw.Draw(sheet)
  draw.text((10,6),m['title']+' · '+m['route']+' / v'+data['version'],font=font,fill='#ecd49c')
  draw.text((10,34),'原始Canvas960×540 · 相邻视口有重叠 · 非拼接概念图',font=small,fill='#afc1ca')
  for i,f in enumerate(frames):
   x,y=i%2*584+4,i//2*350+64;draw.text((x+4,y),f['label']+'  camera='+str(round(f['camera'])),font=small,fill='#cfbd97');im=Image.open(folder/f['file']).convert('RGB');sheet.paste(im.resize((576,324),Image.Resampling.LANCZOS),(x,y+21))
  sheet.save(folder/'sheets'/('map-'+str(m['stage'])+'-'+kind+'.png'),optimize=True)
serialized=json.dumps(data,ensure_ascii=False).replace('</','<\\/')
html=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>地图渲染截图册</title><style>*{box-sizing:border-box}body{margin:0;background:#101922;color:#d9e2e2;font:15px/1.6 system-ui,'Microsoft Yahei'}header{padding:18px 24px;border-bottom:1px solid #50616c}header h1{margin:0}#summary{font-size:12px;word-break:break-all}main{display:grid;grid-template-columns:240px 1fr;gap:20px;padding:20px}nav{position:sticky;top:10px;height:calc(100vh - 170px);overflow:auto}button{font:inherit}nav button{display:block;width:100%;padding:8px;text-align:left;background:none;border:0;border-left:3px solid transparent;color:#b7cad1;cursor:pointer}nav button[aria-current=true]{border-color:#ddbb7d;background:#253946;color:#ffe6ba}h2{color:#ecd49c;margin:0}.note{padding:12px;border-left:3px solid #ddbb7d;background:#20313c;margin:10px 0}.tools{display:flex;gap:20px;flex-wrap:wrap;margin:14px 0}a{color:#9bd6e0}.frames{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}figure{margin:0;background:#080f15}figcaption{padding:6px 10px}.world{position:relative;cursor:zoom-in}.world img{width:100%;aspect-ratio:16/9;display:block}.world svg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.meta{padding:6px 10px;color:#9eb8c0;font-size:12px}dialog{background:#101922;border:1px solid #78909b;max-width:98vw;color:#fff}dialog::backdrop{background:#000c}dialog img{width:960px;max-width:94vw;display:block}dialog button{float:right}@media(max-width:1100px){.frames{grid-template-columns:1fr}main{grid-template-columns:210px 1fr}}</style><header><h1>五界十五关 · 地图渲染截图册</h1><div id="summary"></div><div>静态规范场景 · 原始960×540截图 · 可叠加真实平台与补给位置 · 不代表自然通关</div></header><main><nav id="maps"></nav><article><h2 id="title"></h2><div class="note" id="review"></div><div class="tools"><label><input type="checkbox" id="boxes">叠加平台／物件范围</label><a id="before">修前</a><a id="after">修后</a><a id="route" target="_blank">路线对照图</a><a id="states" target="_blank">状态对照图</a><span>点击图片放大原图</span></div><div id="frames" class="frames"></div></article></main><dialog id="zoom"><button onclick="this.closest('dialog').close()">关闭</button><img alt="地图原始截图"></dialog><script>const DATA=__DATA__;let current=Number(new URLSearchParams(location.search).get('map')||0);const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');document.querySelector('#summary').textContent='v'+DATA.version+' · '+DATA.maps.length+'关 · '+DATA.maps.reduce((n,m)=>n+m.frames.length,0)+'张 · '+DATA.sha256;document.querySelector('#maps').innerHTML=DATA.maps.map(m=>'<button data-stage="'+m.stage+'">'+esc(m.title)+'</button>').join('');function overlay(f){const rect=(b,color,h)=>'<rect x="'+(b.x-f.camera)+'" y="'+b.y+'" width="'+b.w+'" height="'+(h||b.h)+'" fill="none" stroke="'+color+'" stroke-width="1"/>';return'<svg viewBox="0 0 960 540">'+f.platforms.map(b=>rect(b,b.enabled?'#83dbd6':'#ffb262',b.solid?b.h:16)).join('')+rect(f.camp,'#f2d48c')+f.pickups.map(b=>rect(b,'#94ff9d')).join('')+'</svg>'}function show(){const m=DATA.maps.find(m=>m.stage===current)||DATA.maps[0];document.querySelector('#title').textContent=m.title+' · '+m.route;document.querySelector('#review').textContent=m.review.status+' · '+m.review.notes.join('；');document.querySelector('#before').href='../before/review.html?map='+m.stage;document.querySelector('#after').href='../after/review.html?map='+m.stage;document.querySelector('#route').href='sheets/map-'+m.stage+'-route.png';document.querySelector('#states').href='sheets/map-'+m.stage+'-states.png';document.querySelector('#frames').innerHTML=m.frames.map(f=>'<figure><figcaption>'+esc(f.label)+'</figcaption><div class="world" data-file="'+f.file+'"><img src="'+f.file+'" alt="'+esc(m.title+' '+f.label)+'">'+(document.querySelector('#boxes').checked?overlay(f):'')+'</div><div class="meta">camera='+Math.round(f.camera)+' · '+f.pickups.length+'件固定可见补给 · 缺图='+f.missing.length+'</div></figure>').join('');for(const e of document.querySelectorAll('.world'))e.onclick=()=>{const d=document.querySelector('#zoom');d.querySelector('img').src=e.dataset.file;d.showModal()};for(const b of document.querySelectorAll('nav button'))b.setAttribute('aria-current',Number(b.dataset.stage)===m.stage)}for(const b of document.querySelectorAll('nav button'))b.onclick=()=>{current=Number(b.dataset.stage);show()};document.querySelector('#boxes').onchange=show;show();</script></html>'''.replace('__DATA__',serialized)
(folder/'review.html').write_text(html,encoding='utf8')
print(json.dumps({'gallery':str(folder/'review.html'),'maps':len(data['maps']),'frames':sum(len(m['frames']) for m in data['maps'])}))
